import * as zod from "zod";

export const taskTriggerIntervalSecondsMin = 10;

export const taskTriggerCronMax = 128;

export const taskTriggerTimezoneDefault = `UTC`;
export const taskTriggerOverlapPolicyDefault = `buffer_one`;
export const taskTriggerCatchupSecondsDefault = 300;
export const taskTriggerCatchupSecondsMin = 10;

export const TaskTrigger = zod
  .strictObject({
    type: zod.enum(["now", "at", "interval", "cron"]),
    runAt: zod.iso.datetime({ offset: true }).nullish().describe("For `at`."),
    intervalSeconds: zod
      .int()
      .min(taskTriggerIntervalSecondsMin)
      .nullish()
      .describe("For `interval`."),
    anchorAt: zod.iso
      .datetime({ offset: true })
      .nullish()
      .describe(
        "For `interval`. Runs fall on anchorAt plus whole intervals. Defaults to the creation time.",
      ),
    cron: zod
      .string()
      .max(taskTriggerCronMax)
      .nullish()
      .describe(
        "For `cron`. A cron expression evaluated in `timezone`, for example `0 9 * * 1-5`.",
      ),
    timezone: zod
      .string()
      .default(taskTriggerTimezoneDefault)
      .describe("An IANA time zone for `cron`."),
    overlapPolicy: zod
      .enum(["skip", "buffer_one"])
      .default(taskTriggerOverlapPolicyDefault)
      .describe("What happens when a run is due while the previous one is still going."),
    catchupSeconds: zod
      .int()
      .min(taskTriggerCatchupSecondsMin)
      .default(taskTriggerCatchupSecondsDefault)
      .describe("How late a missed run may still start, for example after a pause or an outage."),
  })
  .describe("When the task runs. `type` determines which fields apply.");

export type TaskTrigger = zod.input<typeof TaskTrigger>;
export type TaskTriggerOutput = zod.output<typeof TaskTrigger>;
